use unicode_width::UnicodeWidthChar;
fn main() {
    // emit ranges of (start, end, width) where width differs from 1
    let mut ranges: Vec<(u32,u32,u8)> = Vec::new();
    let mut cur: Option<(u32,u32,u8)> = None;
    for cp in 0u32..=0x10FFFF {
        let w: u8 = match char::from_u32(cp) {
            Some(c) => c.width().unwrap_or(0) as u8,
            None => 1, // surrogates: unreachable in Rust strings
        };
        match cur {
            Some((s, e, cw)) if cw == w && e + 1 == cp => cur = Some((s, cp, w)),
            Some(r) => { ranges.push(r); cur = Some((cp, cp, w)); }
            None => cur = Some((cp, cp, w)),
        }
    }
    if let Some(r) = cur { ranges.push(r); }
    println!("// (start, end, width) for ranges with width != 1");
    println!("pub static WIDTH_RANGES: &[(u32, u32, u8)] = &[");
    for (s, e, w) in &ranges {
        if *w != 1 { println!("    (0x{:X}, 0x{:X}, {}),", s, e, w); }
