"""Generate a Rust table of display widths following the classic wcwidth-style
rules (zero width for Mn/Me/Cf and Hangul Jamo medial/final, double width for
East Asian Wide/Fullwidth), restricted to characters assigned up to Unicode 12.1.

Usage: gen_width_table.py <path-to-age.rs-with-V13_0..-ranges> > src/width_table.rs
The age file is only used to find code points newer than Unicode 12.1 so they
can be treated as unassigned."""
import re
import sys
import unicodedata

newer = []  # (lo, hi) ranges of code points assigned after 12.1

def parse_age(path):
    txt = open(path, encoding='utf-8').read()
    for ver in ("V13_0", "V14_0", "V15_0", "V15_1", "V16_0", "V17_0"):
        m = re.search(r"pub const %s: &'static \[\(char, char\)\] = &\[(.*?)\];" % ver, txt, re.S)
        if not m:
            continue
        for a, b in re.findall(r"\('((?:\\u\{[0-9A-Fa-f]+\}|\\'|\\\\|[^'])+)',\s*'((?:\\u\{[0-9A-Fa-f]+\}|\\'|\\\\|[^'])+)'\)", m.group(1)):
            newer.append((decode(a), decode(b)))

def decode(s):
    m = re.fullmatch(r"\\u\{([0-9A-Fa-f]+)\}", s)
    if m:
        return int(m.group(1), 16)
    if s == "\\'":
        return ord("'")
    if s == "\\\\":
        return ord("\\")
    return ord(s)

def is_newer(cp):
    for lo, hi in newer:
        if lo <= cp <= hi:
            return True
    return False

# Blocks where unassigned code points default to East Asian Wide.
DEFAULT_WIDE = [(0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xF900, 0xFAFF),
                (0x20000, 0x2FFFD), (0x30000, 0x3FFFD)]

def width(cp):
    if cp < 0x20 or 0x7F <= cp < 0xA0:
        return 0
    if cp == 0xAD:
        return 1
    if 0xD800 <= cp <= 0xDFFF:
        return 1
    c = chr(cp)
    cat = unicodedata.category(c)
    if is_newer(cp):
        cat = 'Cn'
    if cat in ('Mn', 'Me', 'Cf'):
        return 0
    if 0x1160 <= cp <= 0x11FF:
        return 0
    if cat == 'Cn':
        for lo, hi in DEFAULT_WIDE:
            if lo <= cp <= hi:
                return 2
        return 1
    if unicodedata.east_asian_width(c) in ('W', 'F'):
        return 2
    return 1

def main():
    if len(sys.argv) > 1:
        parse_age(sys.argv[1])
    ranges = []
    cur = None
    for cp in range(0x110000):
        w = width(cp)
        if cur and cur[2] == w and cur[1] + 1 == cp:
