    /// Like `opt_str` but yields `default` when the option is present without
    /// a value.
    pub fn opt_default(&self, name: &str, default: &str) -> Option<String> {
        let i = self.idx(name)?;
        match self.vals[i].first() {
            Some(Val::Value(s)) => Some(s.clone()),
            Some(Val::Given) => Some(default.to_string()),
            None => None,
        }
    }

    pub fn opt_strs(&self, name: &str) -> Vec<String> {
        match self.idx(name) {
            Some(i) => self.vals[i]
                .iter()
                .filter_map(|v| match v {
                    Val::Value(s) => Some(s.clone()),
                    Val::Given => None,
                })
                .collect(),
            None => Vec::new(),
        }
    }
}

fn is_arg(s: &str) -> bool {
    s.as_bytes().first() == Some(&b'-') && s.len() > 1
}

fn find(defs: &[OptDef], name: &Name) -> Option<usize> {
    match name {
        Name::Short(c) => defs.iter().position(|d| {
            let mut it = d.short.chars();
            it.next() == Some(*c) && it.next().is_none()
        }),
        Name::Long(s) => defs.iter().position(|d| d.long == s),
    }
}

pub fn parse(defs: &[OptDef], raw: Vec<OsString>) -> Result<Matches, Fail> {
    let mut args: Vec<String> = Vec::with_capacity(raw.len());
    for a in raw {
        match a.into_string() {
            Ok(s) => args.push(s),
            Err(os) => return Err(Fail::UnrecognizedOption(format!("{:?}", os))),
        }
    }
    let mut vals: Vec<Vec<Val>> = vec![Vec::new(); defs.len()];
    let mut free: Vec<String> = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let cur = args[i].clone();
        i += 1;
        if !is_arg(&cur) {
            free.push(cur);
            continue;
        }
        if cur == "--" {
            free.extend(args[i..].iter().cloned());
            break;
        }
        let mut names: Vec<Name> = Vec::new();
        let mut i_arg: Option<String> = None;
        let was_long;
        if cur.as_bytes()[1] == b'-' {
            was_long = true;
            let tail = &cur[2..];
            let mut parts = tail.splitn(2, '=');
            names.push(Name::from_long(parts.next().unwrap()));
            if let Some(rest) = parts.next() {
                i_arg = Some(rest.to_string());
            }
        } else {
            was_long = false;
            for (j, ch) in cur.char_indices().skip(1) {
                let opt = Name::Short(ch);
                let id = match find(defs, &opt) {
                    Some(id) => id,
                    None => return Err(Fail::UnrecognizedOption(opt.text())),
                };
                names.push(opt);
                let follows = matches!(defs[id].has_arg, HasArg::Yes | HasArg::Maybe);
                if follows {
                    let next = j + ch.len_utf8();
                    if next < cur.len() {
                        i_arg = Some(cur[next..].to_string());
                        break;
                    }
                }
            }
        }
        let total = names.len();
        for (pos, nm) in names.iter().enumerate() {
            let name_pos = pos + 1;
            let id = match find(defs, nm) {
                Some(id) => id,
                None => return Err(Fail::UnrecognizedOption(nm.text())),
            };
            match defs[id].has_arg {
                HasArg::No => {
                    if name_pos == total && i_arg.is_some() {
                        return Err(Fail::UnexpectedArgument(nm.text()));
                    }
                    vals[id].push(Val::Given);
                }
                HasArg::Maybe => {
                    if let Some(v) = i_arg.take() {
                        vals[id].push(Val::Value(v));
                    } else if was_long
                        || name_pos < total
                        || i >= args.len()
                        || is_arg(&args[i])
                    {
                        vals[id].push(Val::Given);
                    } else {
                        vals[id].push(Val::Value(args[i].clone()));
                        i += 1;
                    }
                }
                HasArg::Yes => {
                    if let Some(v) = i_arg.take() {
                        vals[id].push(Val::Value(v));
                    } else if i < args.len() {
                        vals[id].push(Val::Value(args[i].clone()));
                        i += 1;
                    } else {
                        return Err(Fail::ArgumentMissing(nm.text()));
                    }
                }
            }
        }
    }
    for (v, d) in vals.iter().zip(defs.iter()) {
        if d.occur != Occur::Multi && v.len() > 1 {
            let name = if d.long.is_empty() { d.short } else { d.long };
            return Err(Fail::OptionDuplicated(name.to_string()));
        }
    }
    Ok(Matches {
        defs: defs.to_vec(),
        vals,
        free,
    })
}

/// Render the option table in the traditional aligned form.
pub fn usage(brief: &str, defs: &[OptDef]) -> String {
    let mut rows: Vec<String> = Vec::new();
    for d in defs {
        let mut row = String::from("    ");
        if d.short.is_empty() {
            row.push_str("    ");
        } else {
            row.push('-');
            row.push_str(d.short);
            if d.long.is_empty() {
                row.push(' ');
            } else {
                row.push_str(", ");
            }
        }
        if !d.long.is_empty() {
            row.push_str("--");
            row.push_str(d.long);
            row.push(' ');
        }
        match d.has_arg {
            HasArg::No => {}
            HasArg::Yes => row.push_str(d.hint),
            HasArg::Maybe => {
                row.push('[');
                row.push_str(d.hint);
                row.push(']');
            }
        }
        let len = row.chars().count();
        if len < 24 {
            for _ in 0..(24 - len) {
                row.push(' ');
            }
        } else {
            row.push('\n');
            row.push_str(&" ".repeat(24));
        }
        let words: Vec<&str> = d.desc.split_whitespace().collect();
        row.push_str(&words.join(" "));
        rows.push(row);
    }
    format!("{}\n\nOptions:\n{}\n", brief, rows.join("\n"))
}
