const UNICODE_FILL: char = '\u{2588}';
const UNICODE_SHADES: [char; 4] = [' ', '\u{2591}', '\u{2592}', '\u{2593}'];

const BRANCH: &str = "\u{251c}\u{2500} "; // ├─
const LAST_BRANCH: &str = "\u{2514}\u{2500} "; // └─
const VERTICAL: &str = "\u{2502}  "; // │
const EMPTY: &str = "   ";
const BAR_EDGE: char = '\u{2502}';

/// Everything that drives a run.
#[derive(Clone, Debug)]
pub struct Config {
    pub depth: u8,
    pub aggr: u64,
    pub usage: bool,
    pub bytes: bool,
    pub files_only: bool,
    pub exclude: Vec<String>,
    pub no_hidden: bool,
    pub ascii: bool,
    pub colors: Option<Colors>,
    pub term_cols: u16,
}

/// Colour table parsed from `LS_COLORS`.
#[derive(Clone, Debug, Default)]
pub struct Colors {
    types: HashMap<String, String>,
    exts: HashMap<String, String>,
}

/// Width of a single character on the terminal, zero for control and
/// combining characters, two for wide East Asian characters.
pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    let table = width_table::WIDTH_RANGES;
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (s, e, w) = table[mid];
        if cp < s {
            hi = mid;
        } else if cp > e {
            lo = mid + 1;
        } else {
            return w as usize;
        }
    }
    1
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Parses an aggregation threshold such as `10`, `512K`, `3M`, `1G` or `2T`.
/// Returns `None` when the text does not look like a size at all.
pub fn parse_size(text: &str) -> Option<u64> {
    let mut chars = text.chars();
    let mut digits = String::new();
    let mut unit: Option<char> = None;
    let mut ok = false;
    while let Some(c) = chars.next() {
        if c.is_ascii_digit() && unit.is_none() {
            digits.push(c);
            ok = true;
        } else if unit.is_none() && ok {
            unit = Some(c);
        } else {
            return None;
        }
    }
    if !ok {
        return None;
    }
    // A plain run of digits followed by at most one character: the digits
    // are expected to fit, anything else is a programming error upstream.
    let number: u64 = digits.parse::<u64>().unwrap();
    let mult = match unit {
        Some('k') | Some('K') => UNIT_KIB,
        Some('m') | Some('M') => UNIT_MIB,
        Some('g') | Some('G') => UNIT_GIB,
        Some('t') | Some('T') => UNIT_TIB,
        _ => 1,
    };
    Some(number.wrapping_mul(mult))
}

/// Human readable size, or plain bytes.
pub fn fmt_size(bytes: u64, plain: bool) -> String {
    if plain || bytes < UNIT_KIB {
        return format!("{} B", bytes);
    }
    let (div, unit) = if bytes < UNIT_MIB {
        (UNIT_KIB, "KiB")
    } else if bytes < UNIT_GIB {
        (UNIT_MIB, "MiB")
    } else if bytes < UNIT_TIB {
        (UNIT_GIB, "GiB")
    } else {
        (UNIT_TIB, "TiB")
    };
    format!("{:.2} {}", bytes as f64 / div as f64, unit)
}

/// Terminal width in columns from the standard output, 80 when unknown.
pub fn terminal_columns() -> u16 {
    #[repr(C)]
    struct WinSize {
        rows: u16,
        cols: u16,
        xpixel: u16,
        ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
        fn isatty(fd: i32) -> i32;
    }
    const TIOCGWINSZ: u64 = 0x5413;
    unsafe {
        if isatty(1) == 0 {
            return 80;
        }
        let mut ws = WinSize {
            rows: 0,
            cols: 0,
            xpixel: 0,
            ypixel: 0,
        };
        if ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize) == 0 {
            ws.cols
        } else {
            80
        }
    }
}

fn os_name(name: &OsStr) -> String {
    match name.to_str() {
        Some(s) => s.to_string(),
        None => "[invalid name]".to_string(),
    }
}

impl Colors {
    /// Reads the colour table from the environment, `None` when unset.
    pub fn from_env() -> Option<Colors> {
        let raw = std::env::var("LS_COLORS").ok()?;
        Some(Colors::parse(&raw))
    }

    fn classify(key: &str) -> (bool, &str) {
        let is_ext = &key[..2] == "*.";
        if is_ext {
            (true, &key[2..])
        } else {
            (false, key)
        }
    }

    pub fn parse(raw: &str) -> Colors {
        let mut colors = Colors::default();
        for part in raw.split(':') {
            if part.is_empty() {
                break;
            }
            let mut kv = part.split('=');
            let key = kv.next().unwrap();
            let value = kv.next().unwrap();
            let (is_ext, name) = Colors::classify(key);
            if is_ext {
                colors.exts.insert(name.to_string(), value.to_string());
            } else {
                colors.types.insert(name.to_string(), value.to_string());
            }
        }
        colors
    }

    fn get(&self, key: &str) -> Option<&String> {
        self.types.get(key)
    }

    /// Finds the escape sequence for a path, following the same precedence
    /// as `ls`: link state, directory flavour, executable bit, extension and
    /// finally the generic file / special file entries.
    pub fn lookup(&self, path: &Path) -> Option<String> {
        let lmeta = fs::symlink_metadata(path).ok()?;
        let meta = fs::metadata(path).ok();
        let mode = lmeta.permissions().mode();
        if lmeta.file_type().is_symlink() {
            if meta.is_some() {
                if let Some(c) = self.get("ln") {
                    return Some(c.clone());
                }
            }
            if let Some(c) = self.get("or") {
                return Some(c.clone());
            }
        }
        let is_dir = meta.as_ref().map(|m| m.is_dir()).unwrap_or(false);
        let is_file = meta.as_ref().map(|m| m.is_file()).unwrap_or(false);
        if is_dir {
            if mode & 0o002 != 0 {
                if let Some(c) = self.get("ow") {
                    return Some(c.clone());
                }
            }
            if let Some(c) = self.get("di") {
                return Some(c.clone());
            }
        }
        if mode & 0o111 != 0 {
            if let Some(c) = self.get("ex") {
                return Some(c.clone());
            }
        }
        if let Some(ext) = path.extension() {
            if let Some(ext) = ext.to_str() {
                if let Some(c) = self.exts.get(ext) {
                    return Some(c.clone());
                }
            }
        }
        if is_file {
            self.get("fi").cloned()
        } else {
            self.get("bd").cloned()
        }
    }
}

/// A node of the scanned tree.
#[derive(Debug)]
pub struct Entry {
    pub name: String,
    pub path: PathBuf,
    pub size: u64,
    pub is_dir: bool,
    /// `Some` when the children are meant to be displayed.
    pub children: Option<Vec<Entry>>,
}

fn entry_size(meta: &fs::Metadata, cfg: &Config) -> u64 {
    if cfg.usage {
        meta.blocks().wrapping_mul(512)
    } else {
        meta.len()
    }
}

fn skip_entry(name: &str, is_dir: bool, cfg: &Config) -> bool {
    if cfg.files_only && is_dir {
        return true;
    }
    if cfg.no_hidden && name.starts_with('.') {
        return true;
    }
    if cfg.exclude.iter().any(|x| x == name) {
        return true;
    }
    false
}

fn report_unreadable(name: &str, err: &io::Error) {
    eprintln!("Couldn't read {} ({:?})", name, err.kind());
}

fn report_entry(err: &io::Error) {
    eprintln!("Couldn't read entry ({:?})", err.kind());
}

/// Total size of a directory's content, without keeping the entries.
fn dir_content_size(path: &Path, name: &str, cfg: &Config) -> u64 {
    let mut total: u64 = 0;
    let iter = match fs::read_dir(path) {
        Ok(it) => it,
        Err(e) => {
            report_unreadable(name, &e);
            return 0;
        }
    };
    for item in iter {
        let dent = match item {
            Ok(d) => d,
            Err(e) => {
                report_entry(&e);
                break;
            }
        };
        let child_name = os_name(&dent.file_name());
        let child_path = dent.path();
        let meta = match fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let is_dir = meta.is_dir();
        if skip_entry(&child_name, is_dir, cfg) {
            continue;
        }
        total = total.wrapping_add(entry_size(&meta, cfg));
        if is_dir {
            total = total.wrapping_add(dir_content_size(&child_path, &child_name, cfg));
        }
    }
    total
}

impl Entry {
    /// Builds the tree rooted at `path`. `depth` is how many more levels
    /// below this entry must keep their children for display.
    pub fn build(path: &Path, name: String, depth: u8, cfg: &Config) -> Entry {
        let meta = fs::symlink_metadata(path).ok();
        let is_dir = meta.as_ref().map(|m| m.is_dir()).unwrap_or(false);
        let mut size = meta.as_ref().map(|m| entry_size(m, cfg)).unwrap_or(0);
        let mut children = None;
        if is_dir {
            if depth > 0 {
                let list = Entry::read_children(path, &name, depth - 1, cfg);
                for c in &list {
                    size = size.wrapping_add(c.size);
                }
                children = Some(list);
            } else {
                size = size.wrapping_add(dir_content_size(path, &name, cfg));
            }
        }
        Entry {
            name,
            path: path.to_path_buf(),
            size,
            is_dir,
            children,
        }
    }

    fn read_children(path: &Path, name: &str, depth: u8, cfg: &Config) -> Vec<Entry> {
        let mut list = Vec::new();
        // First make sure the directory can be opened at all.
        if let Err(e) = fs::read_dir(path) {
            report_unreadable(name, &e);
        }
        let iter = match fs::read_dir(path) {
            Ok(it) => it,
            Err(e) => {
                report_unreadable(name, &e);
                return list;
            }
        };
        for item in iter {
            let dent = match item {
                Ok(d) => d,
                Err(e) => {
                    report_entry(&e);
                    break;
                }
            };
            let child_name = os_name(&dent.file_name());
            let child_path = dent.path();
            let is_dir = match fs::symlink_metadata(&child_path) {
                Ok(m) => m.is_dir(),
                Err(_) => continue,
            };
            if skip_entry(&child_name, is_dir, cfg) {
                continue;
            }
            list.push(Entry::build(&child_path, child_name, depth, cfg));
        }
        list
    }

    /// A synthetic root grouping several paths.
    pub fn collection(children: Vec<Entry>) -> Entry {
        let mut size: u64 = 0;
        for c in &children {
            size = size.wrapping_add(c.size);
        }
        Entry {
            name: "<collection>".to_string(),
            path: PathBuf::new(),
            size,
            is_dir: true,
            children: Some(children),
        }
    }

    fn aggregated(size: u64) -> Entry {
        Entry {
            name: "<aggregated>".to_string(),
            path: PathBuf::new(),
            size,
            is_dir: false,
            children: None,
        }
    }
}

/// Display name of a path given on the command line.
pub fn path_display_name(path: &Path) -> String {
    let is_dir = fs::symlink_metadata(path)
        .map(|m| m.is_dir())
        .unwrap_or(false);
    if is_dir {
        if let Ok(canon) = fs::canonicalize(path) {
            return match canon.file_name() {
                Some(n) => os_name(n),
                None => os_name(canon.as_os_str()),
            };
        }
    }
    match path.file_name() {
        Some(n) => os_name(n),
        None => os_name(path.as_os_str()),
    }
}

/// Layout derived from the terminal width.
struct Layout {
    /// Columns available for the tree prefix plus the name.
    name_cols: u16,
    /// Number of cells in the usage bar.
    bar_cells: usize,
    fill: char,
    shades: [char; 4],
}

impl Layout {
    fn new(cfg: &Config) -> Layout {
        let cols = cfg.term_cols;
        let quarter = cols.wrapping_sub(15) / 4;
        let name_cols = if quarter > 25 { quarter } else { 25 };
        let rest = cols.wrapping_sub(name_cols);
        let bar_cells = (rest as usize).wrapping_sub(22);
        let (fill, shades) = if cfg.ascii {
            (ASCII_FILL, ASCII_SHADES)
        } else {
            (UNICODE_FILL, UNICODE_SHADES)
        };
        Layout {
            name_cols,
            bar_cells,
            fill,
            shades,
        }
    }
}

/// Fits `name` into `width` columns: cut when too long, padded otherwise.
fn fit_name(name: &str, width: usize) -> (String, String) {
    let full = str_width(name);
    let mut out = String::new();
    let mut used = 0usize;
    for c in name.chars() {
        let w = char_width(c);
        if used + w > width {
            break;
        }
        used += w;
        out.push(c);
    }
    let pad = " ".repeat(width.saturating_sub(full));
    (out, pad)
}

/// Derives the bar of a child from the bar of its parent.
fn child_bar(parent: &[char], cells: usize, width: u64, level: usize, layout: &Layout) -> Vec<char> {
    let mut bar: Vec<char> = Vec::with_capacity(cells);
    let threshold = (cells as u64).wrapping_sub(width);
    for (i, &pc) in parent.iter().enumerate() {
        if (i as u64) > threshold {
            bar.push(layout.fill);
        } else if pc == layout.fill && level >= 1 && level - 1 < layout.shades.len() {
            bar.push(layout.shades[level - 1]);
        } else {
            bar.push(pc);
        }
    }
    bar
}

fn ratio_cells(size: u64, cells: usize, denominator: u64) -> u64 {
    if denominator == 0 {
        0
    } else {
        size.wrapping_mul(cells as u64) / denominator
    }
}

fn percent(size: u64, total: u64) -> u64 {
    if total == 0 {
        0
    } else {
        size.wrapping_mul(100) / total
    }
}

/// Prints the whole tree.
pub fn print_tree(root: &Entry, cfg: &Config) {
    let layout = Layout::new(cfg);
    println!("[ {} {} ]", root.name, fmt_size(root.size, cfg.bytes));
    if let Some(children) = &root.children {
        let root_bar: Vec<char> = vec![layout.fill; layout.bar_cells];
        print_children(children, root, "", 1, &root_bar, true, cfg, &layout);
    }
}

#[allow(clippy::too_many_arguments)]
fn print_children(
    children: &[Entry],
    parent: &Entry,
    prefix: &str,
    level: usize,
    parent_bar: &[char],
    top: bool,
    cfg: &Config,
    layout: &Layout,
) {
    // Sort by size, biggest first, keeping directory order for ties.
    let mut shown: Vec<&Entry> = children.iter().collect();
    shown.sort_by(|a, b| b.size.cmp(&a.size));
    let mut aggregated: Option<Entry> = None;
    if parent.name != "<collection>" || parent.path != PathBuf::new() || !top {
        let mut kept = Vec::with_capacity(shown.len());
        let mut sum: u64 = 0;
        let mut any = false;
        for e in shown {
            if e.size < cfg.aggr {
                sum = sum.wrapping_add(e.size);
                any = true;
            } else {
                kept.push(e);
            }
        }
        shown = kept;
        if any {
            aggregated = Some(Entry::aggregated(sum));
        }
    }
    if let Some(a) = &aggregated {
        shown.push(a);
    }
    let denominator = if top {
        shown.iter().map(|e| e.size).max().unwrap_or(0)
    } else {
        parent.size
    };
    let count = shown.len();
    for (i, entry) in shown.iter().enumerate() {
        let last = i + 1 == count;
        let line_prefix = format!("{}{}", prefix, if last { LAST_BRANCH } else { BRANCH });
        let prefix_len = line_prefix.chars().count();
        let avail = layout.name_cols as i64 - prefix_len as i64;
        if avail < 0 {
            return;
        }
        let (name, pad) = fit_name(&entry.name, avail as usize);
        let colored = match (&cfg.colors, cfg.ascii, entry.path.as_os_str().is_empty()) {
            (Some(colors), false, false) => match colors.lookup(&entry.path) {
                Some(code) => format!("\x1b[{}m{}\x1b[0m", code, name),
                None => name,
            },
            _ => name,
        };
        let width = ratio_cells(entry.size, layout.bar_cells, denominator);
        let bar = child_bar(parent_bar, layout.bar_cells, width, level, layout);
        let bar_str: String = bar.iter().collect();
        println!(
            "{}{}{} {}{}{} {:>3}% {:>13}",
            line_prefix,
            colored,
            pad,
            BAR_EDGE,
            bar_str,
            BAR_EDGE,
            percent(entry.size, parent.size),
            fmt_size(entry.size, cfg.bytes)
        );
        if let Some(grandchildren) = &entry.children {
            let child_prefix = format!("{}{}", prefix, if last { EMPTY } else { VERTICAL });
            print_children(
                grandchildren,
                entry,
                &child_prefix,
                level + 1,
                &bar,
                false,
                cfg,
                layout,
            );
        }
    }
}
