use std::ffi::OsString;
use std::path::Path;
use std::process;

use dutree::opts::{self, HasArg, Occur, OptDef};
use dutree::{Colors, Config, Entry};

extern "C" {
    fn signal(signum: i32, handler: usize) -> usize;
}

const SIGPIPE: i32 = 13;

/// A closed pipe on the reading side simply ends the program.
extern "C-unwind" fn on_sigpipe(_sig: i32) {
    process::exit(0);
}

fn option_table() -> Vec<OptDef> {
    vec![
        OptDef { short: "d", long: "depth", hint: "DEPTH", desc: "show directories up to depth N (def 1)", has_arg: HasArg::Maybe, occur: Occur::Optional },
        OptDef { short: "a", long: "aggr", hint: "N[KMG]", desc: "aggregate smaller than N B/KiB/MiB/GiB (def 1M)", has_arg: HasArg::Maybe, occur: Occur::Optional },
        OptDef { short: "s", long: "summary", hint: "", desc: "equivalent to -da, or -d1 -a1M", has_arg: HasArg::No, occur: Occur::Optional },
        OptDef { short: "u", long: "usage", hint: "", desc: "report real disk usage instead of file size", has_arg: HasArg::No, occur: Occur::Optional },
        OptDef { short: "b", long: "bytes", hint: "", desc: "print sizes in bytes", has_arg: HasArg::No, occur: Occur::Optional },
        OptDef { short: "f", long: "files-only", hint: "", desc: "skip directories for a fast local overview", has_arg: HasArg::No, occur: Occur::Optional },
