/// What the colour selection needs to know about a file.
#[derive(Clone, Copy, Debug, Default)]
pub struct FileInfo {
    /// The entry itself is a symbolic link.
    pub is_symlink: bool,
    /// Following links leads to something that exists.
    pub target_exists: bool,
    /// Following links leads to a directory.
    pub is_dir: bool,
    /// Following links leads to a regular file.
    pub is_file: bool,
    /// Permission bits of the entry itself.
    pub mode: u32,
}

impl FileInfo {
    fn gather(path: &Path, lmeta: Option<&fs::Metadata>) -> FileInfo {
        let lmeta = match lmeta {
            Some(m) => m,
            None => return FileInfo::default(),
        };
        let mut info = FileInfo {
            is_symlink: lmeta.file_type().is_symlink(),
            target_exists: true,
            is_dir: lmeta.is_dir(),
            is_file: lmeta.is_file(),
            mode: lmeta.permissions().mode(),
        };
        if info.is_symlink {
            match fs::metadata(path) {
                Ok(m) => {
                    info.is_dir = m.is_dir();
                    info.is_file = m.is_file();
                }
                Err(_) => {
                    info.target_exists = false;
                    info.is_dir = false;
                    info.is_file = false;
                }
            }
        }
        info
    }
}

