    /// Parses the `LS_COLORS` syntax: colon separated `key=value` pairs.
    /// Parsing stops at the first empty element. Keys starting with `*.`
    /// are extension patterns, anything else names a file type.
    pub fn parse(raw: &str) -> Colors {
        let mut colors = Colors::default();
        for part in raw.split(':') {
            if part.is_empty() {
