/// a run of digits optionally followed by a single unit character. Returns
/// `None` when the text does not have that shape.
pub fn parse_size(text: &str) -> Option<u64> {
    let digits_len = text.bytes().take_while(|b| b.is_ascii_digit()).count();
    if digits_len == 0 {
        return None;
    }
    let mut rest = text[digits_len..].chars();
    let unit = rest.next();
    if rest.next().is_some() {
        return None;
    }
    // The shape has been validated; the digits are expected to fit.
    let number: u64 = text[..digits_len].parse::<u64>().unwrap();
    let mult = match unit {
        Some('k') | Some('K') => UNIT_KIB,
        Some('m') | Some('M') => UNIT_MIB,
        Some('g') | Some('G') => UNIT_GIB,
        Some('t') | Some('T') => UNIT_TIB,
        _ => 1,
    };
    Some(number.wrapping_mul(mult))
}

